SELECT 'bookkeeping_family_dict_state' tbl,'initialized_at' col,'datetime' dtype,'NO' nullable,NULL len,'CURRENT_TIMESTAMP' defval
) e LEFT JOIN information_schema.columns c ON c.table_schema=DATABASE() AND c.table_name=e.tbl AND c.column_name=e.col
WHERE c.column_name IS NULL OR c.data_type<>e.dtype OR c.is_nullable<>e.nullable
OR (e.len IS NOT NULL AND c.character_maximum_length<>CAST(e.len AS UNSIGNED))
OR (e.dtype IN ('int','smallint') AND c.column_type NOT LIKE '%unsigned%')
OR (e.dtype='varchar' AND (c.character_set_name<>'utf8mb4' OR c.collation_name<>'utf8mb4_bin'))
OR (e.defval IS NOT NULL AND NOT(UPPER(c.column_default)<=>e.defval))
OR (e.col='active_name_key' AND (c.extra<>'STORED GENERATED' OR c.generation_expression NOT LIKE '%dict_type%'))
UNION ALL
SELECT 'schema_indexes' check_name,COUNT(*) exception_count FROM (
SELECT 'base_dict' tbl,'uk_bookkeeping_dict_name' idx,0 non_unique,'scope_type,family_group_id,user_id,dict_type,active_name_key' cols
UNION ALL
SELECT 'base_dict' tbl,'uk_dict_previous' idx,0 non_unique,'previous_id' cols
UNION ALL
SELECT 'base_dict' tbl,'idx_bookkeeping_scope' idx,1 non_unique,'scope_type,family_group_id,user_id,dict_type,deleted' cols
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'PRIMARY' idx,0 non_unique,'id' cols
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'uk_record_tag_source' idx,0 non_unique,'record_id,dict_type,source_dict_id' cols
UNION ALL
SELECT 'bookkeeping_record_tag_snapshot' tbl,'idx_record_tag_type' idx,1 non_unique,'record_id,dict_type' cols
UNION ALL
SELECT 'bookkeeping_family_dict_state' tbl,'PRIMARY' idx,0 non_unique,'family_group_id' cols
) e LEFT JOIN (
 SELECT table_name,index_name,non_unique,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols,
 SUM(sub_part IS NOT NULL) prefix_columns,MIN(is_visible) is_visible
 FROM information_schema.statistics WHERE table_schema=DATABASE()
 GROUP BY table_name,index_name,non_unique
) s ON s.table_name=e.tbl AND s.index_name=e.idx
WHERE s.index_name IS NULL OR s.non_unique<>e.non_unique OR s.cols<>e.cols OR s.prefix_columns<>0 OR s.is_visible<>'YES'
)
SELECT check_name,exception_count,IF(exception_count=0,'PASS','FAIL') result FROM checks
UNION ALL SELECT 'OVERALL',SUM(exception_count),IF(SUM(exception_count)=0,'PASS','FAIL') FROM checks;
SELECT COUNT(*) total_bills,SUM(dictionary_snapshot_status=1) complete_bills,COALESCE(SUM(amount),0) bill_amount FROM bookkeeping_records;
SELECT b.metric,b.row_count expected_rows,v.row_count actual_rows,b.amount expected_amount,v.amount actual_amount,
 b.fingerprint expected_fingerprint,v.fingerprint actual_fingerprint,
 (b.row_count=v.row_count AND (b.amount<=>v.amount) AND b.fingerprint=v.fingerprint) unchanged
 FROM bookkeeping_dictionary_migration_baseline b JOIN (
 SELECT 'records' metric,COUNT(*) row_count,COALESCE(SUM(amount),0) amount,
 BIT_XOR(CRC32(CONCAT_WS('|',id,user_id,COALESCE(expense_user_id,'NULL'),record_category,amount,record_date,group_id,share_state,deleted))) fingerprint FROM bookkeeping_records
 UNION ALL SELECT 'wallet',COUNT(*),COALESCE(SUM(wallet_balance),0),BIT_XOR(CRC32(CONCAT_WS('|',id,user_id,wallet_balance,wallet_assets,deleted))) FROM bookkeeping_wallet
 UNION ALL SELECT 'relations',COUNT(*),NULL,BIT_XOR(CRC32(CONCAT_WS('|',id,business_type,business_id,dict_id))) FROM base_dict_business_relation
 UNION ALL SELECT 'other_dict',COUNT(*),NULL,BIT_XOR(CRC32(CONCAT_WS('|',id,user_id,dict_type,dict_code,dict_name,dict_status,sort,deleted))) FROM base_dict WHERE dict_type NOT IN (4001,4002,4011)
 ) v ON b.metric=v.metric ORDER BY b.metric;
COMMIT;
